tests.setup:
const { prisma } = await app("lib/prisma.ts");
const { toggleVoteAction } = await app("lib/actions/feedback.ts");
const { requireUser } = await app("lib/workspace.ts");

// Create a user
const user = await prisma.user.create({ data: { email: "user@example.com", name: "Test User", passwordHash: "hash" } });

// Set session to simulate signed-in user
set_session({ user: { id: user.id, email: user.email, name: user.name } });

// Create a workspace
const workspace = await prisma.workspace.create({ data: { name: "Test Workspace", slug: "test-workspace", webhookSecret: "secret" } });

// Add membership for user in workspace
await prisma.membership.create({ data: { userId: user.id, workspaceId: workspace.id, role: "MEMBER" } });

// Create a feedback item in the workspace
const feedback = await prisma.feedback.create({ data: { title: "Test Feedback", body: "This is a test feedback.", workspaceId: workspace.id, authorId: user.id } });

tests.body:
arranged();

// Run two concurrent toggleVoteAction calls without awaiting between them to simulate race condition
const p1 = toggleVoteAction(workspace.slug, feedback.id);
const p2 = toggleVoteAction(workspace.slug, feedback.id);

let err1 = null;
let err2 = null;
try { await p1; } catch (e) { err1 = e; }
try { await p2; } catch (e) { err2 = e; }

record('error1', err1 ? String(err1.message) : null);
record('error2', err2 ? String(err2.message) : null);

// Count votes for this feedback
const votesCount = await prisma.vote.count({ where: { feedbackId: feedback.id } });
record('votesCount', votesCount);

// Harm observed if either call errored with unique constraint violation
const uniqueErrorOccurred = (err1 && err1.message.includes('Unique constraint failed')) || (err2 && err2.message.includes('Unique constraint failed'));
harm_observed(uniqueErrorOccurred, 'Unique constraint violation occurred due to concurrent vote toggling');

arranged();

let error = null;
try {
  await toggleVoteAction(workspace.slug, feedback.id);
} catch (e) {
  error = e;
}
record('error', error ? String(error.message) : null);

const votesCount = await prisma.vote.count({ where: { feedbackId: feedback.id } });
record('votesCount', votesCount);

check(error === null, 'No error thrown when toggling vote first time');
check(votesCount === 1, 'Exactly one vote exists after toggling vote first time');

arranged();

// Call toggleVoteAction once to create a vote
await toggleVoteAction(workspace.slug, feedback.id);

// Check that exactly one vote exists for this feedback and user
const votes = await prisma.vote.findMany({ where: { feedbackId: feedback.id, userId: user.id } });

check(votes.length === 1, 'Exactly one vote exists after toggling vote once');
check(votes[0].feedbackId === feedback.id, 'Vote is associated with the correct feedback');
check(votes[0].userId === user.id, 'Vote is associated with the correct user');

